package cn.dreamingfish.launcher.loaders;
import cn.dreamingfish.launcher.downloads.TaskFailure;
import cn.dreamingfish.launcher.storage.LauncherJson;
import cn.dreamingfish.launcher.vanilla.SafeInstallPath;
import com.fasterxml.jackson.databind.JsonNode;
import java.io.*;
import java.nio.file.Path;
import java.util.*;
import java.util.zip.*;

/** 校验过的官方归档仅作输入；完整installer主程序不会执行。 */
public record ForgeInstallerProfile(LoaderIdentity identity,ForgeClientProfile client,byte[] versionJson,Map<String,String> data,List<Processor> processors,List<MavenLibrary> libraries,Map<String,byte[]> embedded){
 public record Processor(String jar,List<String> classpath,List<String> args,Map<String,String> outputs){}
 public static ForgeInstallerProfile read(Path archive,LoaderIdentity identity,String game)throws IOException{
  try(var zip=new ZipFile(archive.toFile())){var names=new HashSet<String>();var entries=zip.entries();long expanded=0;while(entries.hasMoreElements()){var entry=entries.nextElement();String name=entry.getName();if(entry.isDirectory()){name=name.substring(0,name.length()-1);if(name.isEmpty())continue;}SafeInstallPath.parse(name);if(!names.add(entry.getName())||names.size()>10000||entry.getSize()<0||(expanded+=entry.getSize())>2L*1024*1024*1024)throw new IllegalArgumentException("核心归档过大或条目重复");}
   var n=LauncherJson.read(read(zip,"install_profile.json",2*1024*1024),2*1024*1024);if(!n.path("spec").isInt()||n.path("spec").intValue()!=1||!game.equals(LauncherJson.text(n,"minecraft",128))||!ForgeClientProfile.id(identity,game).equals(LauncherJson.text(n,"version",256))||!"/version.json".equals(LauncherJson.text(n,"json",128)))throw new IllegalArgumentException("尚未支持此核心安装格式");byte[] version=read(zip,"version.json",2*1024*1024);var client=ForgeClientProfile.parse(version,identity,game);var data=new LinkedHashMap<String,String>();var embedded=new LinkedHashMap<String,byte[]>();var values=n.path("data");if(!values.isObject()||values.size()>128)throw new IllegalArgumentException("核心数据表无效");var fields=values.fields();while(fields.hasNext()){var e=fields.next();String key=e.getKey();if(!key.matches("[A-Z][A-Z0-9_]{0,63}")||Set.of("ROOT","SIDE","INSTALLER","MINECRAFT_JAR","LIBRARY_DIR").contains(key))throw new IllegalArgumentException("核心数据标识无效");if(!e.getValue().has("client"))continue;String value=LauncherJson.text(e.getValue(),"client",1024);if(value.startsWith("[")){coordinate(value);}else if(value.startsWith("/data/")){String path=value.substring(1);SafeInstallPath.parse(path);embedded.put(path,read(zip,path,32*1024*1024));}else if(!(value.startsWith("'")&&value.endsWith("'")&&value.substring(1,value.length()-1).matches("[A-Za-z0-9_.+\\-]{1,256}")))throw new IllegalArgumentException("未识别的核心数据值");data.put(key,value);}
   var steps=n.path("processors");if(!steps.isArray()||steps.size()>64)throw new IllegalArgumentException("核心处理步骤无效");var processors=new ArrayList<Processor>();for(var step:steps){if(step.has("sides")&&!ForgeClientProfile.strings(step.path("sides"),2).contains("client"))continue;String jar=LauncherJson.text(step,"jar",512);knownTool(jar);var cp=ForgeClientProfile.strings(step.path("classpath"),128);cp.forEach(MavenLibrary::path);var args=ForgeClientProfile.strings(step.path("args"),128);if(jar.contains(":installertools:")){int task=args.indexOf("--task");if(task<0||task+1>=args.size()||!Set.of("MCP_DATA","DOWNLOAD_MOJMAPS","MERGE_MAPPING").contains(args.get(task+1)))throw new IllegalArgumentException("未支持的安装处理任务");}var outputs=new LinkedHashMap<String,String>();if(step.has("outputs")){if(!step.path("outputs").isObject()||step.path("outputs").size()>32)throw new IllegalArgumentException("核心输出表无效");var it=step.path("outputs").fields();while(it.hasNext()){var e=it.next();if(!e.getValue().isTextual())throw new IllegalArgumentException("核心输出摘要无效");outputs.put(e.getKey(),e.getValue().textValue());}}processors.add(new Processor(jar,cp,args,Map.copyOf(outputs)));}
   return new ForgeInstallerProfile(identity,client,version,Map.copyOf(data),List.copyOf(processors),ForgeClientProfile.libraries(n.path("libraries"),identity.kind()),Map.copyOf(embedded));
  }catch(IllegalArgumentException invalid){throw new TaskFailure("UNSUPPORTED_LOADER_FORMAT",invalid.getMessage());}
 }
 static String coordinate(String value){if(!value.startsWith("[")||!value.endsWith("]"))throw new IllegalArgumentException("核心坐标引用无效");return MavenLibrary.path(value.substring(1,value.length()-1));}
 private static void knownTool(String coordinate){MavenLibrary.path(coordinate);String[] parts=coordinate.split(":");if(!Set.of("net.minecraftforge:installertools","net.minecraftforge:ForgeAutoRenamingTool","net.minecraftforge:binarypatcher","net.neoforged.installertools:installertools","net.neoforged.installertools:jarsplitter","net.neoforged.installertools:binarypatcher","net.neoforged:AutoRenamingTool").contains(parts[0]+":"+parts[1]))throw new IllegalArgumentException("未识别的核心客户端处理器");}
 private static byte[] read(ZipFile zip,String path,int max)throws IOException{var entry=zip.getEntry(path);if(entry==null||entry.isDirectory()||entry.getSize()<0||entry.getSize()>max)throw new IOException("核心归档缺少或超限："+path);try(var in=zip.getInputStream(entry)){byte[] bytes=in.readNBytes(max+1);if(bytes.length!=entry.getSize()||bytes.length>max)throw new IOException("核心归档条目长度不符");var crc=new CRC32();crc.update(bytes);if(crc.getValue()!=entry.getCrc())throw new IOException("核心归档条目校验失败");return bytes;}}
}
